import { DOCUMENT } from '@angular/common';
import { DestroyRef, Injectable, computed, effect, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';

type ThemeName = 'light' | 'dark';

export type NavIcon =
  | 'lucideLayoutDashboard'
  | 'lucideUsers'
  | 'lucideTarget'
  | 'lucideShieldAlert'
  | 'lucideUserPlus'
  | 'lucideSettings';

interface NavEntry {
  readonly path: string;
  readonly label: string;
  readonly icon: NavIcon;
  // Path prefixes that light this entry up. Roster also owns the hero detail screen.
  readonly prefixes: readonly string[];
}

export const NAV: readonly NavEntry[] = [
  { path: '/dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard', prefixes: ['/dashboard'] },
  { path: '/roster', label: 'Roster', icon: 'lucideUsers', prefixes: ['/roster', '/detail/'] },
  { path: '/missions', label: 'Missions', icon: 'lucideTarget', prefixes: ['/missions'] },
  { path: '/threats', label: 'Threats', icon: 'lucideShieldAlert', prefixes: ['/threats'] },
  { path: '/recruit', label: 'Recruit', icon: 'lucideUserPlus', prefixes: ['/recruit'] },
  { path: '/settings', label: 'Settings', icon: 'lucideSettings', prefixes: ['/settings'] },
];

const THEME_STORAGE_KEY = 'hero-ops-theme';

// The shell's state: the theme choice and the navigation. Component-scoped, so it lives and dies with App.
@Injectable()
export class AppViewModel {
  private readonly router = inject(Router);
  private readonly document = inject(DOCUMENT);
  private readonly view = this.document.defaultView;
  private readonly media = this.view?.matchMedia('(prefers-color-scheme: dark)') ?? null;

  private readonly storedTheme = signal<ThemeName | null>(this.readStoredTheme());
  private readonly systemDark = signal<boolean>(this.media?.matches ?? false);

  // A stored choice always wins. With no choice, the operating system decides.
  readonly dark = computed(
    () => (this.storedTheme() ?? (this.systemDark() ? 'dark' : 'light')) === 'dark',
  );
  readonly themeLabel = computed(() =>
    this.dark() ? 'Switch to light theme' : 'Switch to dark theme',
  );

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: this.router.url },
  );

  readonly nav = computed(() => {
    const path = this.url();
    return NAV.map((entry) => ({
      ...entry,
      active: entry.prefixes.some((prefix) => path.startsWith(prefix)),
    }));
  });

  readonly crumbs = computed<string[]>(() => {
    const path = this.url().split(/[?#]/)[0];
    const section = NAV.find((entry) => entry.prefixes.some((prefix) => path.startsWith(prefix)));
    if (!section) {
      return ['Hero Ops Console'];
    }
    if (path.startsWith('/detail/')) {
      return [section.label, `Hero ${path.split('/')[2] ?? ''}`];
    }
    return [section.label];
  });

  constructor() {
    if (this.media) {
      const onChange = (event: MediaQueryListEvent) => this.systemDark.set(event.matches);
      this.media.addEventListener('change', onChange);
      inject(DestroyRef).onDestroy(() => this.media?.removeEventListener('change', onChange));
    }

    effect(() => {
      this.document.documentElement.classList.toggle('dark', this.dark());
    });
  }

  toggleTheme(): void {
    const next: ThemeName = this.dark() ? 'light' : 'dark';
    this.storedTheme.set(next);
    this.view?.localStorage.setItem(THEME_STORAGE_KEY, next);
  }

  private readStoredTheme(): ThemeName | null {
    const value = this.view?.localStorage.getItem(THEME_STORAGE_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  }
}
